DROP TABLE IF EXISTS `T_Card_to_Title`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `T_Card_to_Title` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `F_title_name` varchar(30) DEFAULT NULL,
  `F_title_Chinese` varchar(30) DEFAULT NULL,
  `F_title_img` varchar(70) DEFAULT NULL,
  `F_title_must_card` text,
  `F_title_get_methods` text,
  `F_add_hp` int(11) DEFAULT '0',
  `F_add_mp` int(11) DEFAULT '0',
  `F_add_ac` int(11) DEFAULT '0',
  `F_add_mc` int(11) DEFAULT '0',
  `F_add_hits` int(11) DEFAULT '0',
  `F_add_miss` int(11) DEFAULT '0',
  `F_add_speed` int(11) DEFAULT '0',
  `F_add_hprate` int(11) DEFAULT '0',
  `F_add_mprate` int(11) DEFAULT '0',
  `F_add_acrate` int(11) DEFAULT '0',
  `F_add_mcrate` int(11) DEFAULT '0',
  `F_add_hitsrate` int(11) DEFAULT '0',
  `F_add_missrate` int(11) DEFAULT '0',
  `F_add_speedrate` int(11) DEFAULT '0',
  `F_dxsh` int(11) DEFAULT '0',
  `F_hitshp` int(11) DEFAULT '0',
  `F_hitsmp` int(11) DEFAULT '0',
  `F_shjs` int(11) DEFAULT '0',
  `F_sdmp` int(11) DEFAULT '0',
  `F_szmp` int(11) DEFAULT '0',
  `F_addmoney` int(11) DEFAULT '0',
  `F_time` int(11) DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `index_title_name` (`F_title_name`) USING BTREE
) ENGINE=MyISAM AUTO_INCREMENT=49 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

