  `nscf` tinyint(1) unsigned DEFAULT '0',
  `subhp` int(11) unsigned DEFAULT '0',
  `addhp` int(11) unsigned DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_battlefielduser_uid` (`uid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
