CREATE TABLE `bb` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `name` varchar(50) NOT NULL DEFAULT '',
  `wx` tinyint(1) unsigned DEFAULT '1',
  `ac` int(11) unsigned DEFAULT '0',
  `mc` int(11) unsigned DEFAULT '0',
  `hp` int(11) unsigned DEFAULT '0',
  `mp` int(11) unsigned DEFAULT '0',
  `speed` int(11) DEFAULT NULL,
  `hits` int(11) DEFAULT NULL,
  `miss` int(11) DEFAULT NULL,
  `imgstand` varchar(50) DEFAULT NULL,
  `imgack` varchar(50) DEFAULT NULL,
  `imgdie` varchar(50) DEFAULT NULL,
  `skillist` varchar(255) DEFAULT NULL,
  `czl` varchar(50) DEFAULT NULL,
  `kx` varchar(255) DEFAULT NULL,
