  `subyl` smallint(5) unsigned DEFAULT '0',
  `subsl` smallint(5) unsigned DEFAULT '0',
  `subxl` smallint(5) unsigned DEFAULT '0',
  `subdl` smallint(5) unsigned DEFAULT '0',
  `subfl` smallint(5) unsigned DEFAULT '0',
  `subhl` smallint(5) unsigned DEFAULT '0',
  `subkl` smallint(5) unsigned DEFAULT '0',
  `headimg` varchar(50) DEFAULT NULL,
  `cardimg` varchar(50) DEFAULT NULL,
