DROP TABLE IF EXISTS `guild`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `guild` (
  `id` int(6) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) DEFAULT NULL,
  `info` varchar(255) DEFAULT NULL COMMENT '家族公告',
  `creator_id` varchar(255) DEFAULT NULL COMMENT '创建者id',
  `president_id` int(11) DEFAULT NULL COMMENT '会长id',
  `honor` int(11) DEFAULT '0' COMMENT '荣誉',
  `level` tinyint(3) DEFAULT '1' COMMENT '等级',
  `shop_level` tinyint(3) DEFAULT '1' COMMENT '家族商店等级',
  `number_of_member` tinyint(3) DEFAULT '1' COMMENT '成员数',
  `create_time` int(10) DEFAULT NULL,
  `victory_times` smallint(4) DEFAULT NULL COMMENT '胜利次数',
  `failed_times` smallint(4) DEFAULT NULL COMMENT '失败次数',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uq_guild_name` (`name`),
  KEY `lvl` (`level`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

