DROP TABLE IF EXISTS `statistics`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `statistics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `datetime` varchar(20) DEFAULT NULL,
  `area` varchar(20) DEFAULT NULL,
  `registernum` int(10) DEFAULT NULL,
  `avenum` varchar(20) DEFAULT '0',
  `averagenum` varchar(10) DEFAULT NULL,
  `highnum` int(10) DEFAULT '0',
  `loginnum` int(10) DEFAULT NULL,
  `consumenum` int(10) DEFAULT '0',
  `yuanbao` int(10) DEFAULT NULL,
  `Renminbi` varchar(20) DEFAULT NULL,
  `remarks` varchar(255) DEFAULT '运行正常',
  `type` varchar(10) DEFAULT NULL,
  `czyuanbao` varchar(20) DEFAULT '0',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
