DROP TABLE IF EXISTS `task`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `task` (
  `id` int(11) unsigned NOT NULL AUTO_INCREMENT,
  `title` varchar(100) DEFAULT NULL,
  `fromnpc` varchar(10) DEFAULT '0',
  `frommsg` text,
  `okmsg` varchar(255) DEFAULT NULL,
  `oknpc` tinyint(3) unsigned DEFAULT '0',
  `okneed` varchar(255) DEFAULT NULL,
  `result` varchar(255) DEFAULT NULL,
  `cid` varchar(50) DEFAULT '0',
  `limitlv` varchar(255) DEFAULT '0',
  `hide` tinyint(3) unsigned DEFAULT '1',
  `xulie` tinyint(3) unsigned DEFAULT '0',
  `flags` tinyint(3) unsigned DEFAULT '0',
  `color` tinyint(3) unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=1872 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=DYNAMIC;
