DROP TABLE IF EXISTS `war_map`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `war_map` (
  `id` smallint(4) NOT NULL AUTO_INCREMENT,
  `name` varchar(50) DEFAULT NULL,
  `descs` varchar(255) DEFAULT NULL,
  `enter_condition` varchar(50) DEFAULT 'lvl:1,czl:1',
  `type` tinyint(1) DEFAULT '1',
  `opened` varchar(254) DEFAULT '0',
  `difficult_level` varchar(20) DEFAULT '',
  `cooling_time` int(6) DEFAULT '0',
  `player_num` tinyint(2) DEFAULT '0',
  `wuxing_damage` smallint(4) DEFAULT '0',
  `img` varchar(50) DEFAULT '',
  `start_battle_id` int(8) DEFAULT '0',
  `teamimg` varchar(50) DEFAULT '',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=906 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
/*!40101 SET character_set_client = @saved_cs_client */;

